package catalog

import (
	"errors"
	"fmt"
	"path/filepath"
	"slices"
	"strings"

	"github.com/Qfour/falco-ctf-app/internal/catalog/challengeid"
)

// ScenarioFile is the name of the generated file of a scenarios/<id>/ directory (D5).
const ScenarioFile = "scenario.yaml"

// Scenario is a scenarios/<id>/scenario.yaml (ADR-0055 D5): a course flattened into the
// ordered challenges one event runs, generated by cmd/gen-scenarios from the directory's
// module.yaml or course.yaml (Compose, ComposeSolo). It is the one type of that file: the
// generator decodes what it rendered with DecodeScenario, and LoadScenario (the scoreboard,
// LoadScored) reads the file with the same function. It has no tactics (D6:
// gen-attack-layer.py is the one derivation) and no flags (C6). Its requirements (D6, S3a)
// are derived from the scope's catalog (DeriveRequirements, requirements.go).
type Scenario struct {
	ID           string               `yaml:"id"`
	Title        string               `yaml:"title"`
	Challenges   []string             `yaml:"challenges"`
	Source       ScenarioSource       `yaml:"source"`
	Requirements ScenarioRequirements `yaml:"requirements"`
}

// ScenarioSource is D5's `source`: what the scenario was composed from.
type ScenarioSource struct {
	Kind    string           `yaml:"kind"`
	Modules []ScenarioModule `yaml:"modules"`
}

// ScenarioModule is one module of a source, in course order. Edition is empty when the
// course uses the module's own duration.
type ScenarioModule struct {
	ID      string `yaml:"id"`
	Version int    `yaml:"version"`
	Edition string `yaml:"edition"`
}

// DecodeScenario decodes a scenario.yaml strictly (decodeSource, the rules of module.yaml
// and course.yaml: one document, no anchor, alias or merge key, no unknown or repeated key
// at any depth, so a tactics or flags key is an error, and so is an unknown key of
// requirements) and holds it to the shape Compose gives:
//   - id is a scenario name, title is not empty;
//   - challenges lists one or more challenge ids, none twice (a duplicate would put the
//     mission twice in the order the scoreboard walks while the restricted catalog holds
//     it once: C1);
//   - source.kind is module or course, source.modules lists one or more modules, each with
//     a scenario name, a version of at least 1 and an empty or valid edition, none twice;
//     a module's own scenario has exactly that module, with no edition (D6);
//   - requirements and its four keys are written, none null (a file without them is
//     refused, not read as "nothing required"), in the one form the generator writes
//     (requirementsShape: detect and exfil a plain true or false, answers and rules lists
//     of strings), and each list is in DeriveRequirements' form: answers are challenge ids
//     of challenges, rules are rule names, both sorted with nothing twice. Whether the
//     values are the scope's is LoadScored's.
//
// It does not look at the comment lines (the generator's header).
func DecodeScenario(data []byte) (Scenario, error) {
	doc, err := sourceDocument(data)
	if err != nil {
		return Scenario{}, err
	}
	if err := requirementsShape(doc); err != nil {
		return Scenario{}, err
	}
	var s Scenario
	if err := decodeStrictBytes(data, &s); err != nil {
		return Scenario{}, err
	}
	if err := s.validate(); err != nil {
		return Scenario{}, err
	}
	return s, nil
}

func (s Scenario) validate() error {
	if err := checkName("id", s.ID); err != nil {
		return err
	}
	switch {
	case strings.TrimSpace(s.Title) == "":
		return errors.New("title is empty")
	case len(s.Challenges) == 0:
		return errors.New("no challenges listed")
	}
	for _, id := range s.Challenges {
		if !challengeid.Valid(id) {
			return fmt.Errorf("challenge %q is not a challenge id (%s)", id, challengeid.Pattern)
		}
	}
	if err := noRepeat("challenge", s.Challenges); err != nil {
		return err
	}
	src := s.Source
	if src.Kind != KindModule && src.Kind != KindCourse {
		return fmt.Errorf("source.kind %q is neither %q nor %q", src.Kind, KindModule, KindCourse)
	}
	if len(src.Modules) == 0 {
		return errors.New("source.modules is empty")
	}
	ids := make([]string, 0, len(src.Modules))
	for _, m := range src.Modules {
		if err := checkName("source.modules id", m.ID); err != nil {
			return err
		}
		if m.Version < 1 {
			return fmt.Errorf("source.modules %q: version must be at least 1, got %d", m.ID, m.Version)
		}
		if m.Edition != "" {
			if err := checkEditionName(m.Edition); err != nil {
				return fmt.Errorf("source.modules %q: %w", m.ID, err)
			}
		}
		ids = append(ids, m.ID)
	}
	if err := noRepeat("source.modules id", ids); err != nil {
		return err
	}
	if src.Kind == KindModule && (len(src.Modules) != 1 || src.Modules[0].ID != s.ID || src.Modules[0].Edition != "") {
		return fmt.Errorf("source.kind %s: source.modules must be the module %q alone, with no edition (ADR-0055 D6)", KindModule, s.ID)
	}
	return s.Requirements.validate(s.Challenges)
}

// LoadScenario reads the scenario at path, which is scenarios/<id>/scenario.yaml. It is
// fail-closed, and the path of every refusal is named:
//   - the file is a regular file (a symlink is refused) named scenario.yaml, and
//     DecodeScenario accepts it;
//   - its id is the name of its directory (ADR-0055 D2 / C1: the scoreboard, the platform
//     and deploy-user.sh name a scenario by its directory);
//   - the directory holds exactly one source, module.yaml or course.yaml, that LoadSource
//     accepts, and source.kind is that file's kind (D5: a hand-written scenario.yaml, with
//     no source to generate it from, is refused).
//
// It does not compose the source again to compare it with the file: the generator's
// --check does that, in the required test job (cmd/gen-scenarios/realtree_test.go), and a
// course's composition needs every module of scenarios/, which the scoreboard does not read.
// Nor does it look for the generator's header: the source file is what makes a scenario
// generated. Nor does it compare the requirements with the scope (it has no catalog):
// LoadScored does, from the scope's catalog alone.
func LoadScenario(path string) (Scenario, error) {
	data, err := readRegular(path)
	if err != nil {
		return Scenario{}, fmt.Errorf("scenario: %w", err)
	}
	if base := filepath.Base(path); base != ScenarioFile {
		return Scenario{}, fmt.Errorf("scenario %q: the file is named %q, not %s (ADR-0055 D5)", path, base, ScenarioFile)
	}
	s, err := DecodeScenario(data)
	if err == nil {
		err = idIsDir(s.ID, path)
	}
	if err != nil {
		return Scenario{}, fmt.Errorf("scenario %q: %w", path, err)
	}
	src, err := LoadSource(filepath.Dir(path))
	if err != nil {
		return Scenario{}, fmt.Errorf("scenario %q: %w (a scenario.yaml is generated from its directory's source, ADR-0055 D5)", path, err)
	}
	kind := KindCourse
	if src.Module != nil {
		kind = KindModule
	}
	if s.Source.Kind != kind {
		return Scenario{}, fmt.Errorf("scenario %q: source.kind is %q, but its directory holds a %s (ADR-0055 D5)", path, s.Source.Kind, kind)
	}
	return s, nil
}

// LoadScenarios reads every <root>/<name>/scenario.yaml (root is the scenarios/ directory)
// with LoadScenario, in path order, and returns them. Any file LoadScenario refuses is an
// error (a broken sibling is not skipped), and so is no file at all (a wrong root must not
// read as "nothing to check"). Every id is its directory's name (LoadScenario), so no two
// scenarios share one.
func LoadScenarios(root string) ([]Scenario, error) {
	paths, err := filepath.Glob(filepath.Join(root, "*", ScenarioFile))
	if err != nil {
		return nil, fmt.Errorf("list scenarios under %q: %w", root, err)
	}
	if len(paths) == 0 {
		return nil, fmt.Errorf("no <name>/%s found under %q", ScenarioFile, root)
	}
	slices.Sort(paths)
	out := make([]Scenario, 0, len(paths))
	for _, p := range paths {
		s, err := LoadScenario(p)
		if err != nil {
			return nil, err
		}
		out = append(out, s)
	}
	return out, nil
}

// ErrEvadeAfterInvestigate wraps the refusal of a challenge order that puts an
// evade challenge after an investigate challenge (ADR-0056 V39, A3b-5).
var ErrEvadeAfterInvestigate = errors.New("an evade challenge is placed after an investigate challenge")

// checkPlacement is the course placement rule (ADR-0056 A3b-5 / V39): in order,
// no evade challenge comes after an investigate challenge.
//
// Why: the evade clean gate taints only the participant's CURRENT mission
// (CurrentMission = the first unsolved id in order), and an investigate challenge
// has no forbidden rule of its own. A participant who leaves an investigate
// challenge unsolved (one question left) keeps it current, and while it is current
// a fire of a rule that a LATER evade challenge forbids taints nobody (ADR-0003 W2,
// which ADR-0056 extends to the investigate type). Putting every evade challenge
// before the first investigate challenge means an unsolved investigate challenge
// can never be current while an evade challenge is still ahead.
//
// order is the order the scoreboard walks: the scenario's explicit order, or the
// sorted challenge ids when no scenario is pinned (LoadScored hands over the same
// slice it returns as Scored.Order, so the rule is checked on the order that
// defines "current"). An id of order that is not in cat is an error (fail-closed;
// Restrict has refused it already for a scenario). Every offending evade challenge
// is named.
func checkPlacement(cat Catalog, order []string) error {
	firstInvestigate := ""
	var late []string
	for _, id := range order {
		ch, ok := cat[id]
		if !ok {
			return fmt.Errorf("placement check: challenge %q is not in the catalog", id)
		}
		switch ch.Type {
		case TypeInvestigate:
			if firstInvestigate == "" {
				firstInvestigate = id
			}
		case TypeEvade:
			if firstInvestigate != "" {
				late = append(late, id)
			}
		}
	}
	if len(late) == 0 {
		return nil
	}
	return fmt.Errorf("%w: %s after the investigate challenge %q (ADR-0003 W2 / ADR-0056 V39: an investigate challenge "+
		"has no forbidden rule, so while it is current a forbidden-rule fire taints no later evade challenge; "+
		"put every evade challenge before the first investigate challenge)",
		ErrEvadeAfterInvestigate, strings.Join(late, ", "), firstInvestigate)
}

// Restrict returns a new Catalog containing only the named challenges. It is
// fail-closed: an id with no matching challenge is an error, so a typo'd
// scenario manifest is loud rather than silently dropping a mission.
func (c Catalog) Restrict(ids []string) (Catalog, error) {
	out := make(Catalog, len(ids))
	for _, id := range ids {
		ch, ok := c[id]
		if !ok {
			return nil, fmt.Errorf("scenario references unknown challenge %q", id)
		}
		out[id] = ch
	}
	return out, nil
}
